// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { SearchProps } from "./search.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { Combobox } from "@components/combobox";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Search";

// Generate child element class names for the component, should match available style slots
export const SearchClasses = {
  root: "exp-textura_search",
  input: "exp-textura_search_input",
  content: "exp-textura_search_content",
  item: "exp-textura_search_item",
  recentItem: "exp-textura_search_recent_item",
  prefix: "exp-textura_search_prefix",
  suffix: "exp-textura_search_suffix",
  group: "exp-textura_search_group",
  groupLabel: "exp-textura_search_group_label",
  divider: "exp-textura_search_divider",
  clearIconButton: "exp-textura_search_clear_icon_button",
  removeItemButton: "exp-textura_search_remove_item_button",
  itemHighlighted: "exp-textura_combobox_item_active",
  itemSelected: "exp-textura_combobox_item_selected",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: SearchProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<SearchProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    [`.${SearchClasses.input}`]: {
      ...styleSlots?.input,
    },

    [`.${SearchClasses.content}`]: {
      ...styleSlots?.content,
    },

    [`.${SearchClasses.item}`]: {
      ...styleSlots?.item,
    },

    [`.${SearchClasses.recentItem}`]: {
      ...styleSlots?.recentItem,
    },

    [`.${SearchClasses.prefix}`]: {
      ...styleSlots?.prefix,
    },

    [`.${SearchClasses.suffix}`]: {
      ...styleSlots?.suffix,
    },

    [`.${SearchClasses.clearIconButton}`]: {
      ...styleSlots?.clearIconButton,
    },

    [`.${SearchClasses.group}`]: {
      ...styleSlots?.group,
    },

    [`.${SearchClasses.groupLabel}`]: {
      ...styleSlots?.groupLabel,
    },

    [`.${SearchClasses.divider}`]: {
      ...styleSlots?.divider,
    },

    [`.${SearchClasses.removeItemButton}`]: {
      marginInlineStart: "auto",
      ...styleSlots?.removeItemButton,
    },

    [`.${SearchClasses.itemHighlighted}`]: {
      ...styleSlots?.itemHighlighted,
    },

    [`.${SearchClasses.itemSelected}`]: {
      ...styleSlots?.itemSelected,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledSearch = styled(Combobox, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<SearchProps>((props) => generateStyles(props));
